        /// <summary>
        /// Stable symmetric Givens rotation (Golub &amp; Van Loan): returns c, s, r such that
        /// [[c, s], [-s, c]] · [a, b]ᵀ = [r, 0]ᵀ, with r = ±‖(a,b)‖ chosen for cancellation safety.
        /// Zero -> +1 sign convention (matches <see cref="Helpers.signOrOne"/>).
        /// </summary>
        static void SymGivens(float a, float b, out float c, out float s, out float r)
        {
            if (b == (float)0)
            {
                c = Helpers.signOrOne(a);
                s = (float)0;
                r = math.abs(a);
            }
            else if (a == (float)0)
            {
                c = (float)0;
                s = Helpers.signOrOne(b);
                r = math.abs(b);
            }
            else if (math.abs(b) > math.abs(a))
            {
                float t = a / b;
                s = Helpers.signOrOne(b) / math.sqrt((float)1 + t * t);
                c = s * t;
                r = b / s;
            }
            else
            {
                float t = b / a;
                c = Helpers.signOrOne(a) / math.sqrt((float)1 + t * t);
                s = c * t;
                r = a / c;
            }
        }

